static List<Opcode> DiffList<T>(IReadOnlyList<T> a, IReadOnlyList<T> b) where T : IEquatable<T>
{
    int n = a.Count, m = b.Count;
    // LCS 长度表（从右下角往回递推）
    var dp = new int[n + 1, m + 1];
    for (int i = n - 1; i >= 0; i--)
        for (int j = m - 1; j >= 0; j--)
            dp[i, j] = a[i].Equals(b[j]) ? dp[i + 1, j + 1] + 1 : Math.Max(dp[i + 1, j], dp[i, j + 1]);

