        for t in &tasks {
            let mut g = self.inner.tasks.lock().unwrap();
            if let Some(x) = g.iter_mut().find(|x| x.id == t.id) {
                x.updated_at = Some(x.updated_at.unwrap_or(0) + 1);
            }
        }
        self.inner.upsert(tasks)
    }

