pub(crate) fn strip_frontmatter(text: &str) -> &str {
    let text = text.strip_prefix('\u{feff}').unwrap_or(text);
    // 起止 `---` 必须独占一行，避免被文档内的水平分割线 / 示例截断
    let mut lines = text.split_inclusive('\n');
    let Some(first) = lines.next() else { return text; };
    if first.trim_end() != "---" {
        return text;
    }
    let body = &text[first.len()..];
    match body.find("\n---") {
        Some(end) => {
            // 仅当 `---` 之后只剩行结束或 EOF 时才算合法结尾
            let after = &body[end + 4..];
            if after.is_empty() || after.starts_with('\n') {
                body[end + 4..].trim_start_matches('\n')
            } else {
                text
            }
        }
        None => text,
    }
}

