/// RAII 注册守卫：构造即注册、Drop 即反注册。
/// 用 Arc<()> 作为身份令牌，归属判定比较指针地址而非业务字段，
/// 杜绝同 sid+subagent_id 重用导致的 ABA 误删。
pub(crate) struct SubagentSessionGuard {
    session_id: String,
    identity: std::sync::Arc<()>,
}

impl SubagentSessionGuard {
    pub(crate) fn new(session_id: &str, ctx: SubagentSessionCtx) -> Self {
        let identity = std::sync::Arc::new(());
        register_subagent_session(session_id, ctx, &identity);
        Self { session_id: session_id.to_string(), identity }
    }
}

impl Drop for SubagentSessionGuard {
    fn drop(&mut self) {
        let mut m = lock_subagent_sessions();
        if m.get(&self.session_id)
            .map(|c| std::sync::Arc::ptr_eq(&c.identity, &self.identity))
            .unwrap_or(false)
        {
            m.remove(&self.session_id);
        }
    }
}

